settings.start_filament_gcode:
{if printer_notes!~/.*(MK4IS|XLIS|MK4S|MK3.9S|COREONE).*/}
M900 K{if nozzle_diameter[filament_extruder_id]==0.4}0.07{elsif nozzle_diameter[filament_extruder_id]==0.25}0.12{elsif nozzle_diameter[filament_extruder_id]==0.3}0.09{elsif nozzle_diameter[filament_extruder_id]==0.35}0.08{elsif nozzle_diameter[filament_extruder_id]==0.6}0.04{elsif nozzle_diameter[filament_extruder_id]==0.5}0.05{elsif nozzle_diameter[filament_extruder_id]==0.8}0.02{else}0{endif} ; Legacy LA
{else}
M572 S{if nozzle_diameter[filament_extruder_id]==0.4}0.053{elsif nozzle_diameter[filament_extruder_id]==0.5}0.042{elsif nozzle_diameter[filament_extruder_id]==0.6}0.032{elsif nozzle_diameter[filament_extruder_id]==0.8}0.018{elsif nozzle_diameter[filament_extruder_id]==0.25}0.18{elsif nozzle_diameter[filament_extruder_id]==0.3}0.1{else}0{endif} ; Pressure advance
{endif}

M142 S36 ; set heatbreak target temp

; Filament gcode
{local pressure_advance = 0.04}
{if printer_notes=~/.*DUPLICATOR_MODE.*/}
M572 D0:1 S{pressure_advance}
{else}
M572 D{current_extruder} S{pressure_advance}
{endif}

; Filament gcode
{local pressure_advance = 0.0}
{if printer_notes=~/.*DUPLICATOR_MODE.*/}
M572 D0:1 S{pressure_advance}
{else}
M572 D{current_extruder} S{pressure_advance}
{endif}

; Filament gcode
{local pressure_advance = 0.0}
{if printer_notes=~/.*DUPLICATOR_MODE.*/}
M572 D0:1 S{pressure_advance}
{else}
M572 D{current_extruder} S{pressure_advance}
{endif}
